/**
 * The role template and the collector reference are what the registry says.
 *
 * Both are generated by `npm run gen:collectors -w @sightline/api`; this fails
 * while either is stale, which is what stops a collector gaining an AWS call
 * that customers' roles do not grant.
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import {
  renderCollectorDocs,
  withTemplateBlock,
} from "../apps/api/src/scan/collectors/generated.js";
import { COLLECTORS } from "../apps/api/src/scan/collectors/registry.js";

const root = fileURLToPath(new URL("../", import.meta.url));
const template = readFileSync(`${root}infra/readonly-role.yaml`, "utf8");
const STALE = "stale: run `npm run gen:collectors -w @sightline/api` and commit the result";

describe("generated from the collector registry", () => {
  it("the role template grants every action a collector calls", () => {
    expect(template, STALE).toBe(withTemplateBlock(template, COLLECTORS));
  });

  it("the collector reference lists them", () => {
    const docs = readFileSync(`${root}apps/api/src/scan/collectors/README.md`, "utf8");
    expect(docs, STALE).toBe(renderCollectorDocs(COLLECTORS));
  });

  it("no collector calls an action the template denies", () => {
    // The deny wins, so the collector would be refused on every scan.
    const deny = template.slice(template.indexOf("Sid: NeverReadCustomerData"));
    const denied = [...deny.slice(0, deny.indexOf("Resource:")).matchAll(/- "([a-z0-9-]+:\w+)"/g)];
    const called = new Set(Object.values(COLLECTORS).flatMap((p) => p.permissions));
    expect(denied.map((m) => m[1]).filter((a) => called.has(a!))).toEqual([]);
  });

  it("keeps the role's inline policies inside IAM's 10,240-character limit", () => {
    // Every action is a quoted string in the template; the rest of a policy
    // document is a few hundred characters of structure per statement.
    const actions = [...template.matchAll(/- "([a-z0-9-]+:[\w*]+)"/g)].map((m) => m[1]!);
    expect(actions.join('","').length + 1_500).toBeLessThan(10_240);
  });
});
